const rows = $input.all().map(item => item.json).filter(row => row['Invoice ID']);
const today = new Date();
today.setHours(0, 0, 0, 0);

function parseDate(value) {
  if (!value) return null;
  const date = new Date(value);
  return Number.isNaN(date.getTime()) ? null : date;
}

function daysBetween(a, b) {
  const ms = 24 * 60 * 60 * 1000;
  const left = new Date(a);
  const right = new Date(b);
  left.setHours(0, 0, 0, 0);
  right.setHours(0, 0, 0, 0);
  return Math.round((left - right) / ms);
}

const actionable = [];

for (const row of rows) {
  const dueDate = parseDate(row['Due Date']);
  if (!dueDate) continue;

  const invoiceId = String(row['Invoice ID']);
  const clientName = row['Client Name'] || 'there';
  const clientEmail = row['Client Email'] || '';
  const amount = Number(row.Amount || 0);
  const currency = row.Currency || 'USD';
  const reminderCount = Number(row['Reminder Count'] || 0);
  const owner = row.Owner || 'Finance team';
  const daysUntilDue = daysBetween(dueDate, today);
  const daysOverdue = Math.max(0, -daysUntilDue);
  const lastReminderDate = parseDate(row['Last Reminder Date']);
  const daysSinceReminder = lastReminderDate ? daysBetween(today, lastReminderDate) : 999;

  let stage = '';
  let shouldSend = false;
  let escalationNeeded = false;
  let recommendedAction = 'Send standard payment reminder.';

  if (daysUntilDue === 3 && reminderCount === 0) {
    stage = 'Due Soon';
    shouldSend = true;
    recommendedAction = 'Send a friendly reminder before the due date.';
  } else if (daysOverdue >= 1 && daysOverdue <= 7 && daysSinceReminder >= 3) {
    stage = 'First Overdue Reminder';
    shouldSend = true;
    recommendedAction = 'Ask for payment confirmation or expected payment date.';
  } else if (daysOverdue >= 8 && daysOverdue <= 14 && daysSinceReminder >= 4) {
    stage = 'Second Overdue Reminder';
    shouldSend = true;
    recommendedAction = 'Warn that the invoice is overdue and request a payment date.';
  } else if (daysOverdue >= 15 && daysSinceReminder >= 5) {
    stage = 'Final Notice';
    shouldSend = true;
    escalationNeeded = true;
    recommendedAction = 'Escalate internally and consider pausing work or service access.';
  }

  if (amount >= 2000 && daysOverdue >= 7) {
    escalationNeeded = true;
    if (!stage) stage = 'High Value Escalation';
    shouldSend = true;
    recommendedAction = 'High-value overdue invoice needs owner review.';
  }

  if (!shouldSend || !clientEmail) continue;

  const formattedAmount = `${currency} ${amount.toFixed(2)}`;
  const subject = stage === 'Due Soon'
    ? `Friendly reminder: invoice ${invoiceId} is due soon`
    : `${stage}: invoice ${invoiceId} is overdue`;

  const message = stage === 'Due Soon'
    ? `Hi ${clientName},<br><br>This is a friendly reminder that invoice ${invoiceId} for ${formattedAmount} is due on ${row['Due Date']}.<br><br>If payment is already scheduled, thank you. Otherwise, please let us know if you need anything from our side.<br><br>Best regards`
    : `Hi ${clientName},<br><br>Our records show that invoice ${invoiceId} for ${formattedAmount} is ${daysOverdue} day(s) overdue.<br><br>Please confirm when payment will be completed or reply if there is an issue we should review.<br><br>Best regards`;

  const escalationReason = escalationNeeded
    ? `${stage}; ${daysOverdue} days overdue; reminder count ${reminderCount}; amount ${formattedAmount}`
    : '';

  actionable.push({
    json: {
      invoiceId,
      clientName,
      clientEmail,
      amount,
      currency,
      dueDate: row['Due Date'],
      daysUntilDue,
      daysOverdue,
      reminderCount,
      owner,
      stage,
      subject,
      message,
      recommendedAction,
      escalationNeeded,
      escalationReason
    }
  });
}

return actionable.length ? actionable : [{ json: { noInvoicesNeedAction: true, checkedAt: new Date().toISOString() } }];

const rows = $input.all().map(item => item.json).filter(row => row['Invoice ID']);
const today = new Date();
today.setHours(0, 0, 0, 0);

function parseDate(value) {
  const date = new Date(value);
  return Number.isNaN(date.getTime()) ? null : date;
}

function daysBetween(a, b) {
  return Math.round((a - b) / (24 * 60 * 60 * 1000));
}

let totalOpen = 0;
let dueSoon = 0;
let overdue = 0;
let highRisk = 0;
const urgent = [];

for (const row of rows) {
  const amount = Number(row.Amount || 0);
  const due = parseDate(row['Due Date']);
  const currency = row.Currency || 'USD';
  totalOpen += amount;
  if (!due) continue;

  const daysUntilDue = daysBetween(due, today);
  const daysOverdue = Math.max(0, -daysUntilDue);

  if (daysUntilDue >= 0 && daysUntilDue <= 7) dueSoon += amount;
  if (daysOverdue > 0) overdue += amount;
  if (daysOverdue >= 15 || (amount >= 2000 && daysOverdue >= 7)) {
    highRisk += amount;
    urgent.push(`${row['Invoice ID']} | ${row['Client Name']} | ${currency} ${amount.toFixed(2)} | ${daysOverdue} days overdue`);
  }
}

const digest = [
  `Open invoices: ${rows.length}`,
  `Total open amount: ${totalOpen.toFixed(2)}`,
  `Due in next 7 days: ${dueSoon.toFixed(2)}`,
  `Overdue amount: ${overdue.toFixed(2)}`,
  `High-risk overdue amount: ${highRisk.toFixed(2)}`,
  '',
  urgent.length ? 'High-risk invoices:' : 'No high-risk invoices found.',
  ...urgent
].join('\n');

return [{
  json: {
    openInvoiceCount: rows.length,
    totalOpen,
    dueSoon,
    overdue,
    highRisk,
    digest,
    hasOpenInvoices: rows.length > 0
  }
}];
